// Jo Floorplan map — generated by scripts/build_floorplan.py (no dependencies).
// Self-contained: the data is embedded as `const GRAPH = ...;` before this script.
(function () {
  "use strict";
  var G = window.GRAPH || { nodes: [], edges: [], project: {}, outsideServices: [] };
  var nodes = G.nodes || [];
  var topNodes = nodes.filter(function (n) { return !n.parent; });
  var byId = {};
  nodes.forEach(function (n) { byId[n.id] = n; });
  var edges = G.edges || [];
  var searchInput = document.getElementById("search");
  var boardWrap = document.getElementById("board-wrap");
  var board = document.getElementById("board");
  var detail = document.getElementById("detail");
  var detailBack = document.getElementById("detail-back");
  var detailTitle = document.getElementById("detail-title");
  var detailKindEl = document.getElementById("detail-kind");
  var detailSummary = document.getElementById("detail-summary");
  var detailFiles = document.getElementById("detail-files");
  var detailChildren = document.getElementById("detail-children");
  var detailEndpoints = document.getElementById("detail-endpoints");
  var detailScreens = document.getElementById("detail-screens");
  var detailEdges = document.getElementById("detail-edges");
  var resetZoomBtn = document.getElementById("reset-zoom");
  var themeToggle = document.getElementById("theme-toggle");
  var statsEl = document.getElementById("stats");
  var projectSummary = document.getElementById("project-summary");
  var current = null;
  var zoom = { x: 0, y: 0, s: 1 };

  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"]/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c];
    });
  }
  function trunc(s, n) {
    s = String(s == null ? "" : s);
    return s.length > n ? s.slice(0, n - 1) + "\u2026" : s;
  }
  function childrenOf(id) { return nodes.filter(function (n) { return n.parent === id; }); }
  function filesOf(id) { var n = byId[id]; return n ? (n.files || []) : []; }
  function edgesTouching(id) {
    return edges.filter(function (e) { return e.from === id || e.to === id; });
  }
  function matches(n, q) {
    if (!q) return true;
    return (n.id + " " + n.label + " " + (n.summary || "")).toLowerCase().indexOf(q) >= 0;
  }
  function renderStats() {
    var files = nodes.reduce(function (a, n) { return a + filesOf(n.id).length; }, 0);
    var eps = nodes.reduce(function (a, n) { return a + (n.endpoints || []).length; }, 0);
    var svcs = (G.outsideServices || []).length;
    statsEl.textContent = nodes.length + " parts \u00b7 " + files + " files \u00b7 " + eps + " endpoints \u00b7 " + svcs + " services";
    projectSummary.textContent = (G.project && G.project.summary) ? G.project.summary : "";
  }
  function applyTransform() {
    boardWrap.style.transform = "translate(" + zoom.x + "px, " + zoom.y + "px) scale(" + zoom.s + ")";
  }
  function renderBoard() {
    var q = searchInput.value.trim().toLowerCase();
    board.innerHTML = topNodes.filter(function (n) { return matches(n, q); }).map(cardHtml).join("\n");
    board.querySelectorAll("[data-open]").forEach(function (el) {
      el.addEventListener("click", function () { openDetail(el.getAttribute("data-open")); });
    });
  }
  function cardHtml(n) {
    var kids = childrenOf(n.id);
    var kidsLabel = kids.length ? " \u00b7 " + kids.map(function (c) { return c.label; }).join(", ") : "";
    return (
      '<div class="card" data-open="' + esc(n.id) + '" role="button" tabindex="0" title="' + esc(n.summary || "") + '">' +
      '<div class="card-head"><span class="card-id">' + esc(n.label) + "</span>" +
      '<span class="chip chip-' + esc(n.kind) + '">' + esc((n.kind || "").toUpperCase()) + "</span>" +
      '<span class="chip chip-files">' + filesOf(n.id).length + " files</span></div>" +
      '<div class="card-summary">' + esc(trunc(n.summary, 150)) + "</div>" +
      '<div class="card-foot">' + esc(n.id) + kidsLabel + "</div>" +
      "</div>"
    );
  }
  function openDetail(id) {
    if (!byId[id]) { renderBoard(); return; }
    current = id;
    detail.hidden = false;
    boardWrap.style.display = "none";
    renderDetail();
  }
  function closeDetail() {
    current = null;
    detail.hidden = true;
    boardWrap.style.display = "";
    renderBoard();
  }
  function childCardHtml(n) {
    var parts = (n.paths || []).join(", ");
    return (
      '<div class="file-item" data-open="' + esc(n.id) + '" role="button" tabindex="0">' +
      '<span class="file-path">' + esc(n.label) + "</span>" +
      '<span class="file-desc">' + esc(trunc(parts, 90)) + " \u2014 " + esc(trunc(n.summary, 60)) + "</span>" +
      "</div>"
    );
  }
  function noteDiv(text) { return "<div class=\"note\">" + esc(text) + "</div>"; }
  function fileHtml(f) {
    var s = '<div class="file-item"><span class="file-path">' + esc(f.path) + "</span>";
    if (f.description) s += '<span class="file-desc">' + esc(f.description) + "</span>";
    return s + "</div>";
  }
  function epHtml(e) { return "<div class=\"ep\">" + esc(e.method) + " " + esc(e.path) + "</div>"; }
  function screenHtml(s) { return "<div class=\"screen\">" + esc(s) + "</div>"; }
  function edgeHtml(e) {
    var dir = e.to === current
      ? "in:  " + esc(e.from) + " \u2192 " + esc(e.to)
      : "out: " + esc(e.from) + " \u2192 " + esc(e.to);
    var s = '<div class="edge"><span class="edge-dir">' + dir + "</span><span class=\"edge-label\">" + esc(e.label) + "</span>";
    if (e.description) s += '<span class="edge-desc">' + esc(e.description) + "</span>";
    return s + "</div>";
  }
  function renderDetail() {
    var n = byId[current];
    var q = searchInput.value.trim().toLowerCase();
    detailTitle.textContent = n.label;
    if (detailKindEl) { detailKindEl.textContent = n.kind; detailKindEl.className = "chip chip-ui"; }
    detailSummary.textContent = n.summary || "";

    var files = filesOf(current).filter(function (f) {
      return !q || (f.path + " " + (f.description || "")).toLowerCase().indexOf(q) >= 0;
    });
    detailFiles.innerHTML = "<h3>Files</h3>" + (files.length ? files.map(fileHtml).join("") : noteDiv("(no files assigned)"));

    var kids = childrenOf(current).filter(function (k) {
      return !q || (k.label + " " + k.id).toLowerCase().indexOf(q) >= 0;
    });
    detailChildren.innerHTML = "<h3>Children</h3>" + (kids.length ? kids.map(childCardHtml).join("") : noteDiv("(leaf part)"));
    detailChildren.querySelectorAll("[data-open]").forEach(function (el) {
      el.addEventListener("click", function () { openDetail(el.getAttribute("data-open")); });
    });

    detailEndpoints.innerHTML = "<h3>Endpoints</h3>" +
      ((n.endpoints || []).length ? n.endpoints.map(epHtml).join("") : noteDiv("(none \u2014 see parent part)"));

    detailScreens.innerHTML = "<h3>Screens</h3>" +
      ((n.screens || []).length ? n.screens.map(screenHtml).join("") : noteDiv("(no separate screens)"));

    var es = edgesTouching(current);
    detailEdges.innerHTML = "<h3>Connections</h3>" + (es.length ? es.map(edgeHtml).join("") : noteDiv("(no explicit connections)"));
  }
  function zoomPan() {
    boardWrap.addEventListener("wheel", function (e) {
      e.preventDefault();
      var f = e.deltaY < 0 ? 1.12 : 0.89;
      var px = e.clientX, py = e.clientY;
      zoom.x = px - f * (px - zoom.x);
      zoom.y = py - f * (py - zoom.y);
      zoom.s *= f;
      applyTransform();
    }, { passive: false });
    boardWrap.addEventListener("mousedown", function (e) {
      var sx = e.clientX, sy = e.clientY;
      function move(e2) { zoom.x += e2.clientX - sx; zoom.y += e2.clientY - sy; applyTransform(); sx = e2.clientX; sy = e2.clientY; }
      function up() {
        boardWrap.removeEventListener("mousemove", move);
        boardWrap.removeEventListener("mouseup", up);
      }
      if (e.target === board) {
        e.preventDefault();
        boardWrap.addEventListener("mousemove", move);
        boardWrap.addEventListener("mouseup", up);
      }
    });
    boardWrap.addEventListener("dblclick", function () {
      zoom.s = 1; zoom.x = 0; zoom.y = 0;
      applyTransform(); renderBoard();
    });
  }
  function keydown(e) {
    if (e.target && e.target.tagName === "INPUT") return;
    if (e.key === "Escape" && current) closeDetail();
    else if (e.key === "/" && document.activeElement !== searchInput) {
      e.preventDefault();
      searchInput.focus();
    }
  }
  function initTheme() {
    var saved = "";
    try { saved = localStorage.getItem("floorplan-theme"); } catch (err) {}
    if (saved === "dark" || saved === "light") {
      document.documentElement.dataset.theme = saved;
    } else if (window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches) {
      document.documentElement.dataset.theme = "dark";
    } else {
      document.documentElement.dataset.theme = "light";
    }
  }
  function onThemeToggle() {
    var cur = document.documentElement.dataset.theme === "dark" ? "dark" : "light";
    var next = cur === "dark" ? "light" : "dark";
    document.documentElement.dataset.theme = next;
    try { localStorage.setItem("floorplan-theme", next); } catch (err) {}
  }

  renderStats();
  initTheme();
  themeToggle.addEventListener("click", onThemeToggle);
  resetZoomBtn.addEventListener("click", function () {
    zoom = { x: 0, y: 0, s: 1 };
    applyTransform(); renderBoard();
  });
  searchInput.addEventListener("input", renderBoard);
  detailBack.addEventListener("click", closeDetail);
  document.addEventListener("keydown", keydown);
  zoomPan();
  renderBoard();
})();
